import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { personalCodexIntegrationLogic } from 'scenes/settings/user/personalCodexIntegrationLogic'

import { CodexIntegrationStatusEnumApi, type UserCodexIntegrationApi } from '~/generated/core/api.schemas'

import { ModelAccessEnumApi, RuntimeAdapterEnumApi } from 'products/tasks/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codexBillingLogicValues {
    codexIntegration: UserCodexIntegrationApi | null // personalCodexIntegrationLogic
    effectiveCodexModelAccess: ModelAccessEnumApi
    planConnected: boolean
    preferredCodexModelAccess: ModelAccessEnumApi
    selectPlanAfterConnect: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codexBillingLogicActions {
    closeConnectModal: () => {
        value: true
    } // personalCodexIntegrationLogic
    connectCodexSuccess: (
        codexIntegration: UserCodexIntegrationApi,
        payload?: import('~/generated/core/api.schemas').UserCodexAuthTokensApi | undefined
    ) => {
        codexIntegration: UserCodexIntegrationApi
        payload?: import('~/generated/core/api.schemas').UserCodexAuthTokensApi
    } // personalCodexIntegrationLogic
    openConnectModal: (opener: string) => {
        opener: string
    } // personalCodexIntegrationLogic
    connectPlan: (opener: string) => {
        opener: string
    }
    setPreferredCodexModelAccess: (codexModelAccess: ModelAccessEnumApi) => {
        codexModelAccess: ModelAccessEnumApi
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codexBillingLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        planConnected: (codexIntegration: UserCodexIntegrationApi | null) => boolean
        effectiveCodexModelAccess: (
            preferredCodexModelAccess: ModelAccessEnumApi,
            planConnected: boolean
        ) => ModelAccessEnumApi
    }
}

export type codexBillingLogicType = MakeLogicType<
    codexBillingLogicValues,
    codexBillingLogicActions,
    Record<string, any>,
    codexBillingLogicMeta
>

export const codexBillingLogic = kea<codexBillingLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'codexBillingLogic']),

    connect(() => ({
        values: [personalCodexIntegrationLogic, ['codexIntegration']],
        actions: [personalCodexIntegrationLogic, ['openConnectModal', 'closeConnectModal', 'connectCodexSuccess']],
    })),

    actions({
        setPreferredCodexModelAccess: (codexModelAccess: ModelAccessEnumApi) => ({ codexModelAccess }),
        connectPlan: (opener: string) => ({ opener }),
    }),

    reducers({
        preferredCodexModelAccess: [
            ModelAccessEnumApi.PosthogGateway as ModelAccessEnumApi,
            { persist: true },
            {
                setPreferredCodexModelAccess: (_, { codexModelAccess }) => codexModelAccess,
            },
        ],
        selectPlanAfterConnect: [
            false,
            {
                connectPlan: () => true,
                closeConnectModal: () => false,
                connectCodexSuccess: () => false,
            },
        ],
    }),

    selectors({
        planConnected: [
            (s) => [s.codexIntegration],
            (codexIntegration: UserCodexIntegrationApi | null): boolean =>
                codexIntegration?.status === CodexIntegrationStatusEnumApi.Connected,
        ],
        effectiveCodexModelAccess: [
            (s) => [s.preferredCodexModelAccess, s.planConnected],
            (preferred: ModelAccessEnumApi, planConnected: boolean): ModelAccessEnumApi =>
                planConnected ? preferred : ModelAccessEnumApi.PosthogGateway,
        ],
    }),

    listeners(({ actions, values }) => ({
        setPreferredCodexModelAccess: ({ codexModelAccess }) => {
            posthog.capture('codex billing changed', { billing: codexModelAccess })
        },
        connectPlan: ({ opener }) => {
            actions.openConnectModal(opener)
        },
        connectCodexSuccess: () => {
            if (values.selectPlanAfterConnect) {
                actions.setPreferredCodexModelAccess(ModelAccessEnumApi.OwnSubscription)
            }
        },
    })),
])

/**
 * The billing a new run must state, or `null` to leave the field off.
 *
 * Only the billing picker mounts this logic, and it renders only behind the rollout flag, so an unmounted
 * logic means the choice is not offered. When it is offered the choice is always sent: a resumed run
 * otherwise keeps the billing of the run it continues, and the backend refuses a ChatGPT plan on Claude.
 */
export function codexModelAccessForRun(runtimeAdapter: string | null | undefined): ModelAccessEnumApi | null {
    const billing = codexBillingLogic.findMounted()
    if (!billing) {
        return null
    }
    return runtimeAdapter === RuntimeAdapterEnumApi.Codex &&
        billing.values.effectiveCodexModelAccess === ModelAccessEnumApi.OwnSubscription
        ? ModelAccessEnumApi.OwnSubscription
        : ModelAccessEnumApi.PosthogGateway
}
